<template><nav class="pg5-nav-list" aria-label="组件分类" @keydown="key"><details v-for="category in categories" :key="category" open><summary>{{category}} · {{entries.filter(e=>e.category===category).length}}</summary><button v-for="entry in entries.filter(e=>e.category===category)" :key="entry.id" :data-component-id="entry.id" :aria-current="selected===entry.id?'page':undefined" :title="entry.name+' · '+entry.implementationStatus" @click="$emit('select',entry.id)"><span><template v-if="match(entry.title)">{{entry.title.slice(0,match(entry.title)!.start)}}<mark>{{entry.title.slice(match(entry.title)!.start,match(entry.title)!.end)}}</mark>{{entry.title.slice(match(entry.title)!.end)}}</template><template v-else>{{entry.title}}</template></span><small>{{entry.implementationStatus==='已接入真实组件'?'真实':entry.implementationStatus==='仅有内部演示'?'Demo':'待实现'}}</small><span class="pg5-nav-english">{{entry.name}}</span></button></details><p v-if="!entries.length">没有匹配条目</p></nav></template>
<script setup lang="ts">
import {computed} from 'vue'
import type {PlaygroundEntry} from './registry'
const props=defineProps<{entries:PlaygroundEntry[];selected:string;query:string}>(),emit=defineEmits<{select:[id:string]}>()
const categories=computed(()=>[...new Set(props.entries.map(e=>e.category))])
function match(text:string){const q=props.query.trim().toLowerCase();if(!q)return;const start=text.toLowerCase().indexOf(q);return start<0?undefined:{start,end:start+q.length}}
function key(event:KeyboardEvent){if(!['ArrowDown','ArrowUp','Home','End'].includes(event.key))return;const list=Array.from((event.currentTarget as HTMLElement).querySelectorAll<HTMLButtonElement>('button[data-component-id]')).filter(e=>e.getClientRects().length>0);const i=list.indexOf((event.target as HTMLElement).closest('button')!);const next=event.key==='Home'?0:event.key==='End'?list.length-1:(i+(event.key==='ArrowDown'?1:-1)+list.length)%list.length;const el=list[next];if(el){event.preventDefault();el.focus();emit('select',el.dataset.componentId!)}}
</script>
